cd /tmp/yourwork && python3 - <<'EOF'
import zipfile
std = open('/workspace/assets/standard.flf','rb').read()
for meth,name in ((zipfile.ZIP_BZIP2,'zbz2'),(zipfile.ZIP_LZMA,'zlzma')):
    try:
        with zipfile.ZipFile(f'{name}.flf','w',meth) as z: z.writestr('standard.flf', std)
        print(name,"created")
    except Exception as e: print(name,"skip:",e)
EOF
for f in zbz2 zlzma; do [ -f $f.flf ] && { echo "=== $f ==="; /workspace/executable -f /tmp/yourwork/$f Hi 2>&1 | head -2; echo "rc=${PIPESTATUS[0]}"; }; done

cd /tmp/yourwork && python3 - <<'EOF'
def mkfont(path, magic, hb, tags, height=2, tail=""):
    lines = [f"{magic}{hb} {height} {height} 10 -1 0{tail}"]
    for c in range(32,127):
        rows = ['  ','  ']
        for i,r in enumerate(rows):
            lines.append(r+("@@" if i==height-1 else "@"))
    for c in (0xC4,0xD6,0xDC,0xE4,0xF6,0xFC,0xDF):
        for i in range(height):
            lines.append('  '+("@@" if i==height-1 else "@"))
    for code,rows in tags:
        lines.append(f"0x{code:X} tagged")
        for i,r in enumerate(rows):
            lines.append(r+("@@" if i==height-1 else "@"))
    open(path,"wb").write(("\n".join(lines)+"\n").encode('latin-1'))
mkfont("t_ct0.tlf","tlf2a","\x7f",[(0xE9,['TT','TT'])],tail=" 0 0 0")   # codetagcount=0
mkfont("t_ct1.tlf","tlf2a","\x7f",[(0xE9,['TT','TT'])],tail=" 0 0 1")   # codetagcount=1
mkfont("f_ct0.flf","flf2a","$",[(0xE9,['TT','TT'])],tail=" 0 0 0")
EOF
for f in t_ct0 t_ct1 f_ct0; do echo "=== $f byte 0xE9 ==="; printf '\xe9\n' | /workspace/executable -f /tmp/yourwork/$f | head -1 | cat -A; done
